INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65645718', 65645718, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pekerjaan Pengadaan Jasa Konsultan Perencanaan Arsitektur/Sipil Gedung', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 97500000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Melakukan reviu terhadap dokumen perencanaan konstruksi Spesifikasi Teknis, Harga Perkiraan Sendiri (HPS), dan Gambar Perencanaan agar memenuhi ketentuan-ketentuan yang berlaku. 2. Membuat perubahan dokumen perencanaan konstruksi berdasarkan hasil reviu dokumen perencanaan konstruksi (tambah kurang) yang sesuai dengan kondisi lapangan dilihat dari luasan, perubahan struktur (jika ada), ketersediaan barang atau material dan persepsi penyamaan konsep mengacu pada peraturan pemerintah pusat maupun Pemerintah Daerah; 3. Memberikan masukan dan saran agar perencanaan, pelaksanaan, dan pengawasan pekerjaan dapat terlaksana dengan baik, tepat waktu, efisien, efektif dan akuntabel; 4. Menjaga ketepatan waktu pelaksanaan pekerjaan (monitoring progress bobot pekerjaan), kesesuaian spesifikasi (approval material), dan pemenuhan persyaratan kontrak pekerjaan antara Pejabat Pembuat Komitmen dan Penyedia barang dan jasa (pencapaian bobot untuk tagihan);', '1. Melakukan reviu terhadap dokumen perencanaan konstruksi Spesifikasi Teknis, Harga Perkiraan Sendiri (HPS), dan Gambar Perencanaan agar memenuhi ketentuan-ketentuan yang berlaku. 2. Membuat perubahan dokumen perencanaan konstruksi berdasarkan hasil reviu dokumen perencanaan konstruksi (tambah kurang) yang sesuai dengan kondisi lapangan dilihat dari luasan, perubahan struktur (jika ada), ketersediaan barang atau material dan persepsi penyamaan konsep mengacu pada peraturan pemerintah pusat maupun Pemerintah Daerah; 3. Memberikan masukan dan saran agar perencanaan, pelaksanaan, dan pengawasan pekerjaan dapat terlaksana dengan baik, tepat waktu, efisien, efektif dan akuntabel; 4. Menjaga ketepatan waktu pelaksanaan pekerjaan (monitoring progress bobot pekerjaan), kesesuaian spesifikasi (approval material), dan pemenuhan persyaratan kontrak pekerjaan antara Pejabat Pembuat Komitmen dan Penyedia barang dan jasa (pencapaian bobot untuk tagihan); 5. Membantu PPK dalam menyusun HPS untuk pekerjaan konstruksi sekaligus analisa harga satuan dan bahan pekerjaan arsitektur/sipil. 6. Membantu menyiapkan bahan laporan pertanggung jawaban hasil perencanaan, pelaksanaan Pembangunan dan perawatan Gedung pada saat audit internal maupun eksternal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2290631);
