INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65650176', 65650176, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Penyusunan SBKU dan SBKK BGN 2027', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PKT, @ 100000000 )', '1. Penyusunan SBKU dan SBKK BGN 2027 ( 1, PKT, @ 100000000 ); Pengadaan jasa penyusunan Standar Biaya Keluaran Utama (SBKU) dan Standar Biaya Keluaran Khusus (SBKK) Badan Gizi Nasional (BGN) Tahun 2027. Kegiatan ini bertujuan menghasilkan standar biaya yang akurat dan dapat dijadikan dasar perencanaan, penganggaran, serta evaluasi program dan kegiatan BGN.', 'Lingkup pekerjaan mencakup pengumpulan data biaya kegiatan, analisis biaya satuan, penyusunan SBKU dan SBKK lengkap dengan tabel, grafik, dan lampiran pendukung. Dokumen harus disusun secara sistematis, jelas, akurat, dan sesuai ketentuan kebijakan pemerintah. Hasil pekerjaan diserahkan tepat waktu, siap digunakan sebagai acuan resmi perencanaan dan penganggaran BGN Tahun 2027.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2291304);
