INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65686022', 65686022, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA BANDAR UDARA RAHADI OESMAN DI KETAPANG', 'Manajemen Alam Terbuka', 'Jasa Lainnya', 'Penunjukan Langsung', 'Kalimantan Barat, Ketapang (Kab.)', 112578000, 'November 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PKT, @ 112578000 )', 'Pekerjaan ini meliputi kegiatan manajemen alam terbuka guna meningkatkan kemampuan, pengetahuan, serta kerja sama dalam kegiatan di lingkungan alam terbuka yang mendukung pengembangan kapasitas dan koordinasi pegawai.', 'Kegiatan meliputi pelaksanaan kegiatan di alam terbuka seperti pelatihan, pembinaan, dan kegiatan peningkatan kerja sama tim, penyediaan perlengkapan kegiatan, serta pendampingan oleh instruktur atau fasilitator yang kompeten sehingga kegiatan dapat terlaksana dengan aman dan tertib.', 112578000, 'high', 'Kegiatan manajemen alam terbuka/team building untuk pegawai lebih bersifat pembinaan internal dan tidak menunjukkan keterkaitan langsung dengan kebutuhan layanan publik atau operasional inti. Dengan nilai paket penuh pada jasa kegiatan luar ruang, terdapat indikasi kuat belanja tidak prioritas sehingga seluruh nilai layak dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 2294217);
