INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65650221', 65650221, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Fulllboard Meeting', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 90540000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 90, OP, @ 1006000 )', '1. Fulllboard Meeting ( 90, OP, @ 1006000 ); Pengadaan paket fullboard meeting sebanyak 90 orang/paket (OP) untuk mendukung pelaksanaan kegiatan rapat, koordinasi, atau pertemuan resmi. Paket fullboard disediakan guna menunjang kelancaran kegiatan yang dilaksanakan secara intensif dengan fasilitas akomodasi dan konsumsi selama kegiatan berlangsung.', 'Paket fullboard meeting minimal meliputi ruang pertemuan sesuai kapasitas peserta, konsumsi 3 (tiga) kali makan utama dan 2 (dua) kali coffee break per hari, serta 1 (satu) malam akomodasi/kamar hotel (twin sharing/single sesuai kebutuhan). Ruang rapat dilengkapi dengan meja dan kursi standar meeting, sound system, LCD proyektor/layar, pendingin ruangan, dan akses listrik yang memadai. Seluruh fasilitas dalam kondisi baik, bersih, dan layak pakai. Pelaksanaan layanan dilakukan sesuai jadwal dan lokasi kegiatan yang telah ditetapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2295100);
