INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65651241', 65651241, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Fullboard Meeting', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 59950000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 50, OP, @ 1199000 )', '1. Fullboard Meeting ( 50, OP, @ 1199000 ); Fullboard Meeting ( 50, OP, @ 1199000 ); Pengadaan paket fullboard meeting sebanyak 50 orang/paket (OP) untuk mendukung pelaksanaan rapat, koordinasi, atau pembahasan strategis kegiatan. Paket fullboard disediakan guna menunjang kelancaran kegiatan yang dilaksanakan dengan fasilitas akomodasi dan konsumsi selama kegiatan berlangsung.', 'Paket fullboard meeting minimal meliputi ruang pertemuan representatif sesuai kapasitas peserta, konsumsi 3 (tiga) kali makan utama dan 2 (dua) kali coffee break per hari, serta 1 (satu) malam akomodasi/kamar hotel (twin sharing/single sesuai kebutuhan). Ruang rapat dilengkapi meja dan kursi standar meeting, sound system, LCD proyektor/layar, pendingin ruangan (AC), dan akses listrik yang memadai. Fasilitas dalam kondisi baik, bersih, dan layak pakai. Pelaksanaan layanan dilakukan sesuai jadwal dan lokasi kegiatan yang telah ditentukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2295385);
