INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65651234', 65651234, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Pengembangan Sistem Manajemen Kinerja Terintegrasi', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PKT, @ 100000000 )', '1. Pengembangan Sistem Manajemen Kinerja Terintegrasi ( 1, PKT, @ 100000000 ); Pengadaan paket pengembangan sistem manajemen kinerja terintegrasi untuk mendukung perencanaan, pengukuran, pemantauan, dan evaluasi kinerja organisasi secara sistematis dan berbasis teknologi informasi. Sistem ini bertujuan untuk meningkatkan efektivitas pengelolaan kinerja, memastikan keterkaitan antara perencanaan dan capaian kinerja, serta mendukung pengambilan keputusan pimpinan secara tepat dan akurat.', 'Paket pengembangan meliputi analisis kebutuhan sistem, perancangan aplikasi, pengembangan dan implementasi sistem berbasis web/aplikasi, integrasi dengan sistem yang telah ada (apabila diperlukan), uji coba (testing), pelatihan pengguna (user training), serta penyusunan dokumentasi teknis dan panduan penggunaan. Sistem memiliki fitur minimal perencanaan kinerja, cascading kinerja, monitoring realisasi, pelaporan, dan dashboard kinerja. Aplikasi harus user friendly, aman, dan dapat diakses sesuai kebutuhan organisasi. Pelaksanaan pekerjaan diselesaikan sesuai jadwal dan spesifikasi teknis yang telah disepakati.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2295486);
