INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65651228', 65651228, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Jasa Konsultan Pemantauan Rencana Induk BGN 2025-2045', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1, PKT, @ 100000000 )', '1. Jasa Konsultan Pemantauan Rencana Induk BGN 2025-2045 ( 1, PKT, @ 100000000 ); Pengadaan jasa konsultan sebanyak 1 paket untuk mendukung pemantauan dan evaluasi implementasi Rencana Induk Badan Gizi Nasional (BGN) Tahun 2025–2045. Kegiatan ini bertujuan untuk memastikan ketercapaian tujuan strategis, efektivitas pelaksanaan program, serta keselarasan kebijakan dengan arahan pimpinan dan sasaran pembangunan nasional.', 'Paket jasa konsultan meliputi analisis data, pemantauan capaian program, penyusunan laporan pemantauan, rekomendasi strategis, serta pendampingan rapat koordinasi. Konsultan wajib memiliki kompetensi dan pengalaman di bidang perencanaan strategis, evaluasi kebijakan, dan manajemen kinerja. Hasil pekerjaan berupa laporan lengkap dan dokumen pendukung yang sistematis, jelas, dan dapat dipertanggungjawabkan. Pelaksanaan dilakukan sesuai jadwal yang telah ditetapkan dan standar profesionalisme yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2296070);
