INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65651224', 65651224, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Fullday Meeting', 'Barang', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 13770000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 30, OP, @ 459000 )', '1. Fullday Meeting ( 30, OP, @ 459000 ); Fullday Meeting ( 30, OP, @ 459000 ); Pengadaan paket fullday meeting sebanyak 30 orang/paket (OP) untuk mendukung pelaksanaan rapat, koordinasi, atau pembahasan teknis kegiatan. Paket fullday disediakan guna menunjang kelancaran kegiatan yang dilaksanakan selama satu hari penuh tanpa menginap, dengan fasilitas ruang rapat dan konsumsi bagi peserta.', 'Paket fullday meeting minimal meliputi ruang pertemuan yang representatif sesuai kapasitas peserta, konsumsi 1 (satu) kali makan siang dan 2 (dua) kali coffee break, serta perlengkapan rapat berupa meja, kursi, sound system, LCD proyektor/layar, dan pendingin ruangan (AC). Fasilitas dalam kondisi baik, bersih, dan layak pakai. Pelayanan dilaksanakan tepat waktu sesuai jadwal dan lokasi kegiatan yang telah ditentukan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2296072);
