INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65650973', 65650973, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Jasa Konsultan Penyusunan Rencana Aksi Manajemen Perubahan BGN 2025-2029', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1, PKT, @ 100000000 )', '1. Jasa Konsultan Penyusunan Rencana Aksi Manajemen Perubahan BGN 2025-2029 ( 1, PKT, @ 100000000 ); Jasa Konsultan Penyusunan Rencana Aksi Manajemen Perubahan BGN 2025–2029 ( 1, PKT, @ 100000000 ); Pengadaan jasa konsultan sebanyak 1 paket untuk mendukung penyusunan Rencana Aksi Manajemen Perubahan BGN Tahun 2025–2029. Kegiatan ini bertujuan untuk merumuskan strategi, tahapan implementasi, serta indikator keberhasilan manajemen perubahan dalam rangka penguatan Reformasi Birokrasi dan peningkatan kinerja organisasi.', 'Paket pekerjaan meliputi penyusunan metodologi kerja, pengumpulan dan analisis data, reviu dokumen perencanaan dan kebijakan terkait, pelaksanaan diskusi/FGD dengan unit kerja terkait, perumusan peta jalan (roadmap) manajemen perubahan, penyusunan rencana aksi beserta indikator dan target capaian, serta penyusunan laporan akhir dan bahan paparan kepada pimpinan. Tenaga konsultan memiliki kompetensi dan pengalaman di bidang manajemen perubahan dan Reformasi Birokrasi sektor publik. Hasil pekerjaan disampaikan dalam bentuk dokumen tertulis yang sistematis dan bahan presentasi sesuai jadwal yang telah ditetapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2296137);
